@import "tailwindcss";

@layer base {
  :root {
    --bg-abyss: #051216;
    --bg-teal: #092129;
    --bg-teal-elevated: #0E2E38;
    --gold-solar: #F0A824;
    --gold-pale: #F7D58B;
    --coral-surreal: #F26B8A;
    --orange-drape: #FF6B35;
    --marble-parian: #F5EFE4;
    --marble-muted: #C5BCA8;
  }

  html {
    scroll-behavior: smooth;
    background-color: #051216;
    color: #F5EFE4;
    font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  }

  body {
    background-color: #051216;
    overflow-x: hidden;
  }
}

.font-display {
  font-family: 'Cinzel Decorative', 'Cormorant Garamond', Georgia, serif;
}

.font-editorial {
  font-family: 'Cormorant Garamond', Georgia, serif;
}

.font-mono-tech {
  font-family: 'JetBrains Mono', monospace;
}

/* Custom Architectural Clip Paths & Masks */
.clip-arch {
  clip-path: inset(0 0 0 0 round 999px 999px 18px 18px);
}

.clip-arch-invert {
  clip-path: inset(0 0 0 0 round 18px 18px 999px 999px);
}

.clip-pediment {
  clip-path: polygon(50% 0%, 100% 18%, 100% 100%, 0% 100%, 0% 18%);
}

.clip-octagon-ornate {
  clip-path: polygon(22% 0%, 78% 0%, 100% 22%, 100% 78%, 78% 100%, 22% 100%, 0% 78%, 0% 22%);
}

.clip-vesuvian-shard {
  clip-path: polygon(8% 0%, 94% 4%, 100% 88%, 86% 100%, 0% 92%, 3% 14%);
}

.clip-river-slice-left {
  clip-path: polygon(0% 0%, 88% 0%, 100% 100%, 0% 100%);
}

.clip-river-slice-right {
  clip-path: polygon(12% 0%, 100% 0%, 100% 100%, 0% 100%);
}

.clip-keyhole {
  clip-path: polygon(
    25% 0%, 75% 0%, 92% 18%, 92% 48%, 76% 62%, 88% 100%, 12% 100%, 24% 62%, 8% 48%, 8% 18%
  );
}

/* Subtle animated grain & marble patina */
.surreal-noise {
  background-image: radial-gradient(rgba(240, 168, 36, 0.09) 1px, transparent 0),
    radial-gradient(rgba(242, 107, 138, 0.06) 1px, transparent 0);
  background-size: 36px 36px;
  background-position: 0 0, 18px 18px;
}

@keyframes slowSpin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes reverseSlowSpin {
  from {
    transform: rotate(360deg);
  }
  to {
    transform: rotate(0deg);
  }
}

@keyframes floatGentle {
  0%, 100% {
    transform: translateY(0px) rotate(0deg);
  }
  50% {
    transform: translateY(-10px) rotate(0.8deg);
  }
}

@keyframes floatCounter {
  0%, 100% {
    transform: translateY(0px) rotate(0deg);
  }
  50% {
    transform: translateY(9px) rotate(-0.8deg);
  }
}

@keyframes pulseAura {
  0%, 100% {
    opacity: 0.45;
    transform: scale(1);
  }
  50% {
    opacity: 0.8;
    transform: scale(1.06);
  }
}

.animate-spin-slow {
  animation: slowSpin 48s linear infinite;
}

.animate-spin-reverse-slow {
  animation: reverseSlowSpin 64s linear infinite;
}

.animate-float-gentle {
  animation: floatGentle 7s ease-in-out infinite;
}

.animate-float-counter {
  animation: floatCounter 8.5s ease-in-out infinite;
}

.animate-pulse-aura {
  animation: pulseAura 6s ease-in-out infinite;
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 6px;
}

::-webkit-scrollbar-track {
  background: #051216;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #F0A824, #F26B8A);
  border-radius: 999px;
}

